<script lang="ts">
  import { onMount } from "svelte";import AppShell from "../components/AppShell.svelte";import Toast from "../components/Toast.svelte";import { api } from "../lib/api";import type{WifiNetwork,WifiStatus}from"../types";
  let status:WifiStatus|null=null,networks:WifiNetwork[]=[],scanning=false,selected:WifiNetwork|null=null,password="",show=false,message="",good=true;
  onMount(()=>{refresh();scan()});
  async function refresh(){try{status=await api("/api/wifi/status")}catch(e){notify((e as Error).message,false)}}
  async function scan(){scanning=true;try{networks=await api("/api/wifi/scan")}catch(e){notify((e as Error).message,false)}finally{scanning=false}}
  async function connect(){if(!selected)return;try{await api("/api/wifi/connect",{method:"POST",body:JSON.stringify({ssid:selected.ssid,password})});notify(`Connecting to ${selected.ssid}`);selected=null;setTimeout(refresh,2500)}catch(e){notify((e as Error).message,false)}}
  function notify(v:string,ok=true){message=v;good=ok;setTimeout(()=>message="",4500)}
</script>
<AppShell subtitle="Network"><main class="page"><section class="card"><h2>Connection</h2><div class="status"><i class:hotspot={status?.hotspotActive} class:online={status?.connected}></i><div><b>{status?.hotspotActive?"Setup hotspot":status?.connected?status.ssid:"Disconnected"}</b><small>{status?.ip||"No IP address"}</small></div></div></section><section class="card"><h2>Available networks</h2>{#if scanning&&!networks.length}<p class="muted">Scanning…</p>{/if}<div class="networks">{#each networks as network}<button class:active={network.active} class="network" on:click={()=>{selected=network;password=""}}><span><b>{network.ssid}</b><small>{network.security||"Open"}</small></span><span class="signal">{network.signal}%</span></button>{/each}</div><div class="actions"><button on:click={scan} disabled={scanning}>{scanning?"Scanning…":"Scan again"}</button></div></section></main>{#if selected}<div class="overlay"><form class="modal card" on:submit|preventDefault={connect}><h2>Connect to {selected.ssid}</h2><p class="muted">{selected.security||"Open network"}</p>{#if selected.security!=="Open"}<input bind:value={password} type={show?"text":"password"} placeholder="Password" autocomplete="off"><label class="show"><input type="checkbox" bind:checked={show}> Show password</label>{/if}{#if status?.hotspotActive}<p class="warning">This will close the setup hotspot. Reconnect your device to the selected network afterward.</p>{/if}<div class="actions"><button type="button" on:click={()=>selected=null}>Cancel</button><button class="primary">Connect</button></div></form></div>{/if}<Toast {message} {good}/></AppShell>
<style>.status{display:flex;align-items:center;gap:.8rem}.status i{width:13px;height:13px;border-radius:50%;background:#49515d}.status i.online{background:var(--green);box-shadow:0 0 10px var(--green)}.status i.hotspot{background:#d5ad4e}.status small,.network small{display:block;color:var(--muted);margin-top:.2rem}.networks{display:grid;gap:.35rem}.network{display:flex;justify-content:space-between;text-align:left;width:100%;padding:.75rem;background:transparent}.network.active{background:#69c28514;border-color:#69c28566}.signal{color:var(--green)}.overlay{position:fixed;inset:0;background:#000b;display:grid;place-items:center;padding:1rem;z-index:20}.modal{width:min(430px,100%)}.show{display:flex;align-items:center;gap:.5rem;color:var(--muted);margin-top:.6rem}.show input{width:auto}.warning{padding:.7rem;background:#4a3510;border:1px solid #9e6a03;border-radius:7px}</style>
